excels.excel:

EXPORT WITH SHEET="采购入库单", HEADER=true,
    MAPPING={"a":"物料编码","b":"物料名称","c":"入库数量","d":"采购单价","e":"入库金额","f":"供应商"},
    FORMAT={"c":"#,##0","d":"#,##0.00","e":"#,##0.00"},
    FORMULAS={
        E2:'C2*D2',E3:'C3*D3',E4:'C4*D4',E5:'C5*D5',E6:'C6*D6',
        C7:'SUM(C2:C6)',E7:'SUM(E2:E6)'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center}
    }
